<?php require 'config.php'; if(current_user())redirect('account.php');$error='';if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$email=strtolower(trim($_POST['email']??''));$password=$_POST['password']??'';$stmt=db()->prepare('SELECT id,name,email,password_hash,role,status FROM users WHERE email=? LIMIT 1');$stmt->bind_param('s',$email);$stmt->execute();$user=$stmt->get_result()->fetch_assoc();if($user&&$user['status']==='active'&&password_verify($password,$user['password_hash'])){session_regenerate_id(true);unset($user['password_hash']);$_SESSION['user']=$user;redirect('account.php');}$error='Those details did not match an active account.';}page_start('Sign in'); ?>
<section class="section-space"><div class="container"><div class="row justify-content-center"><div class="col-md-6 col-lg-4"><div class="eyebrow">Welcome back</div><h1 class="display-6 mb-4">Sign in.</h1><?php if($error): ?><div class="alert alert-danger"><?= e($error) ?></div><?php endif; ?><form method="post"><input type="hidden" name="csrf" value="<?= csrf_token() ?>"><div class="form-outline mb-3"><input class="form-control" type="email" name="email" required><label class="form-label">Email address</label></div><div class="form-outline mb-2"><input class="form-control" type="password" name="password" required><label class="form-label">Password</label></div><div class="text-end mb-4"><a class="small text-muted" href="forgot_password.php">Forgot password?</a></div><button class="btn btn-dark btn-rounded w-100">Sign in</button></form><p class="small text-muted mt-4">New here? <a href="register.php">Create an account</a></p></div></div></div></section><?php page_end(); ?>